`except BaseException as error:` in `__next__` catches `StopIteration` re-raised by `super().__next__()`. Exclude `StopIteration` so normal completion never enters the error path:

```python
    def __next__(self) -> _RunStreamChunk:
        try:
            return super().__next__()
        except StopIteration:
            raise
        except BaseException as error:
            self._finish_once(error)
            raise
```

Also add a test verifying that normally drained streams complete with `UNSET` status and no `error.type`:

```python
def test_streaming_run_completes_without_error(
    instrument_with_content, span_exporter
) -> None:
    agent = CodeAgent(tools=[], model=FakeCodeModel(), max_steps=3)
    list(agent.run("Test question", stream=True))

    (agent_span,) = spans_by_operation(
        span_exporter.get_finished_spans(), "invoke_agent"
    )
    assert agent_span.status.status_code == StatusCode.UNSET
    assert attr(agent_span, error_attributes.ERROR_TYPE) is None
```
